renderHTML:
__ht__function(data, gv, cache) {option = {
   title: {
        text:'',
        show:false
    },
   tooltip: {
    trigger: 'axis'
  },
  grid: {
    top: '12%',
    left: '3%',
    right: '4%',
    bottom: '3%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    boundaryGap: false,
    data: ['15:30', '16:00', '16:30', '17:00', '17:30', '18:00', '18:30']
  },
  yAxis: {
    type: 'value'
  },
  series: [
    {
      name: '预测历史',
      type: 'line',
      lineStyle: {
          color: 'rgb(100,255,89)',
         width: 2,
        },
        areaStyle: {
        color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [   
        ])
      },
      data: [120, 132, 101, 134 ]
    },
    {
      name: '预测未来',
      type: 'line',
      areaStyle: {
        color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
       
        ])
      },
      data: [, , , 134, 150, 180, 180],
      lineStyle: {
          color: '#rgb(100,255,89)',
         width: 2,
         type: 'dotted' //'dotted'虚线 'solid'实线
        }
    },
    {
      name: '实际',
      type: 'line',
      lineStyle: {
          color: 'rgb(222,82,82)',
         width: 2,
        },
        areaStyle: {
        color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [
       
        ])
      },
      data: [150, 202, 190, 154, , , ]
    }
  ]
};

if (!cache.htmlView) {

    cache.htmlView = document.createElement('div');
    cache.htmlView.style.position = 'absolute';
    cache.htmlChart = echarts.init(cache.htmlView,"dark")

    // layoutHTML will be called when the data needs to be drawing
    cache.htmlView.layoutHTML = function () {
        gv.layoutHTML(data, cache.htmlView, false);
        cache.htmlChart.resize();
    };
}

// update data
//option.xAxis.data = data.a('xAxis.data');
option.series[0].data = data.a('data.line1');
//option.series[0].data = data.a('bindData')["line1"];
option.series[1].data = data.a('data.line2');
option.series[2].data = data.a('data.line3');
option.xAxis.data = data.a('data.xAxis');
data.a('chart.line1color') && (option.series[0].lineStyle.color = data.a('chart.line1color'));
data.a('chart.line2color') && (option.series[1].lineStyle.color = data.a('chart.line2color'));
data.a('chart.line2color') && (option.series[2].lineStyle.color = data.a('chart.line3color'));
if(data.a('chart.text'))
{
    option.title.show=true;
    option.grid.top='12%';
    option.title.text = data.a('chart.text');
}
else
{
    option.grid.top='5%';
    option.title.show=false;
}
// data.a('chart.text') && (option.title.text = data.a('chart.text'));
// data.a('chart.subtext') && (option.title.subtext = data.a('chart.subtext'));
data.a('chart.backgroundColor') && (option.backgroundColor = data.a('chart.backgroundColor'));
cache.htmlChart.setOption(option);

// html for showing
return cache.htmlView;}
